  "implementation": "def solve(case):
    # Validate input structure
    if not isinstance(case, dict) or 'capacity' not in case or 'trials' not in case:
        raise ValueError("Invalid case: missing capacity or trials")
    capacity = case['capacity']
    trials = case['trials']
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("Invalid capacity")
    if not isinstance(trials, list):
        raise ValueError("Trials must be a list")

    # Collect all trial entries
    entries = []
    for idx, trial in enumerate(trials):
        if not isinstance(trial, dict) or 'signature' not in trial or 'reflection' not in trial or 'success' not in trial:
            raise ValueError("Invalid trial structure")
        entries.append({
            'last_trial': idx,
            'reflection': trial['reflection'],
            'signature': trial['signature'],
            'success': trial['success']
        })

    # Deduplicate failure signatures: keep only the most recent failure per signature
    failures_to_keep = {}
    for e in entries:
        if not e['success']:
            sig = e['signature']
            if sig not in failures_to_keep or e['last_trial'] > failures_to_keep[sig]['last_trial']:
                failures_to_keep[sig] = e

    # Build new list: keep all successes and only the kept failures
    kept_entries = []
    for e in entries:
        if e['success']:
            kept_entries.append(e)
        else:
            sig = e['signature']
            if e is failures_to_keep.get(sig):  # identity check works because we stored the same dict
                kept_entries.append(e)

    # Apply capacity limit
    if len(kept_entries) > capacity:
        failures = [e for e in kept_entries if not e['success']]
        successes = [e for e in kept_entries if e['success']]
        # sort by recency descending, then signature ascending
        failures.sort(key=lambda e: (-e['last_trial'], e['signature']))
        successes.sort(key=lambda e: (-e['last_trial'], e['signature']))
        combined = failures + successes
        kept_entries = combined[:capacity]

    # Restore chronological order
    kept_entries.sort(key=lambda e: e['last_trial'])

    memory = kept_entries
    signatures = [e['signature'] for e in memory]

    return {
        'memory': memory,
        'signatures': signatures
    }"
}
